/*	The GraphQL filter needs plain UTC times. Take a generous 30 hours either side of now, then let	*/
/*	Build Dashboard keep only sessions whose own local date is today in TIME_ZONE.	*/
const now_int = Date.now();
return [{ json: {
	fromUtc: new Date(now_int - (30 * 3600000)).toISOString(),
	toUtc: new Date(now_int + (30 * 3600000)).toISOString()
} }];

/*	=== Build the reception dashboard: one card per session running today ===	*/
/*	Expected   = active learners, except anyone 3.0 registered at the door for THIS session. A door	*/
/*	             registration on an earlier day of the course counts as booked by now.	*/
/*	Checked in = learners Administrate holds as Present for THIS session. Read from Administrate, so it	*/
/*	             includes anyone staff marked by hand, not only QR scans.	*/
/*	Walk-ins   = people 3.0 registered at the door for this session. Only our log knows that, because	*/
/*	             Administrate cannot tell a door registration from any other.	*/
const config_obj = $('Config').first().json;
const query_obj = $('Dashboard Page').first().json.query || {};
const zone_str = String(config_obj.TIME_ZONE || 'Europe/London');
const self_str = String(config_obj.PAGE_URL || '');
const refresh_int = parseInt(String(config_obj.REFRESH_SECONDS || '60'), 10) || 60;
const openMinutes_int = parseInt(String(config_obj.OPEN_MINUTES_BEFORE || '120'), 10) || 120;
const closeHours_num = parseFloat(String(config_obj.CLOSE_HOURS_AFTER || '12')) || 12;
const now_int = Date.now();

function escape(value_var)
{
	return String(value_var == null ? '' : value_var).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function localDate(ms_int)
{
	try
	{
		return new Date(ms_int).toLocaleDateString('en-CA', { timeZone: zone_str });
	} catch (error) {
		return new Date(ms_int).toISOString().slice(0, 10);
	}
}

function localTime(ms_int)
{
	try
	{
		return new Date(ms_int).toLocaleTimeString('en-GB', { timeZone: zone_str, hour: '2-digit', minute: '2-digit' });
	} catch (error) {
		return new Date(ms_int).toISOString().slice(11, 16);
	}
}

/*	Header stamp, e.g. "Thursday 24 September 2026 at 20:55 BST". Built from parts so the wording does	*/
/*	not depend on how the server's locale data punctuates dates. The zone label follows GMT and BST.	*/
function localStamp(ms_int)
{
	try
	{
		const parts_ary = new Intl.DateTimeFormat('en-GB', { timeZone: zone_str, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZoneName: 'short' }).formatToParts(new Date(ms_int));
		const part_obj = {};
		parts_ary.forEach(function (item_obj)
		{
			part_obj[item_obj.type] = item_obj.value;
		});
		return part_obj.weekday + ' ' + part_obj.day + ' ' + part_obj.month + ' ' + part_obj.year + ' at ' + part_obj.hour + ':' + part_obj.minute + (part_obj.timeZoneName ? ' ' + part_obj.timeZoneName : '');
	} catch (error) {
		return new Date(ms_int).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
	}
}

const today_str = localDate(now_int);

let response_obj = {};
try
{
	response_obj = $('Fetch Todays Events').first().json || {};
} catch (error) {
	response_obj = {};
}

let events_ary = [];
let truncated_bln = false;
let apiError_str = '';
try
{
	events_ary = response_obj.data.events.edges.map(function (edge_obj) { return edge_obj.node; });
	truncated_bln = !!response_obj.data.events.pageInfo.hasNextPage;
} catch (error) {
	events_ary = [];
	apiError_str = 'Administrate did not return today\'s events.';
}
if (Array.isArray(response_obj.errors) && response_obj.errors.length > 0)
{
	apiError_str = 'Administrate returned an error: ' + String(response_obj.errors[0].message || '');
}

/*	Learners past the first page. Fetch Todays Events reads one page of learners per event; for any event	*/
/*	with more, Fetch More Learners reads every further page up to LEARNER_MAX_PAGES. Pages are grouped by	*/
/*	event id here. pagingDone_obj records events where some page said there was no more. If any page failed,	*/
/*	pagingFailed_bln is set and every paged event is treated as incomplete, because a failed page cannot	*/
/*	say which event it belonged to. Either way the shortfall is flagged on the page, never hidden.	*/
const moreLearners_obj = {};
const pagingDone_obj = {};
let pagingFailed_bln = false;
let morePages_ary = [];
try
{
	if ($('Fetch More Learners').isExecuted)
	{
		morePages_ary = $('Fetch More Learners').all().map(function (item_obj) { return item_obj.json || {}; });
	}
} catch (error) {
	morePages_ary = [];
}
for (const page_obj of morePages_ary)
{
	let pageEvent_obj = null;
	try
	{
		pageEvent_obj = page_obj.data.events.edges[0].node;
	} catch (error) {
		pageEvent_obj = null;
	}
	if (!pageEvent_obj || !pageEvent_obj.learners || (Array.isArray(page_obj.errors) && page_obj.errors.length > 0))
	{
		pagingFailed_bln = true;
		continue;
	}
	const pageEventId_str = String(pageEvent_obj.id);
	if (!moreLearners_obj[pageEventId_str])
	{
		moreLearners_obj[pageEventId_str] = [];
	}
	for (const edge_obj of (pageEvent_obj.learners.edges || []))
	{
		moreLearners_obj[pageEventId_str].push(edge_obj.node);
	}
	if (!(pageEvent_obj.learners.pageInfo && pageEvent_obj.learners.pageInfo.hasNextPage))
	{
		pagingDone_obj[pageEventId_str] = true;
	}
}
const incompleteEvents_obj = {};

/*	Walk-ins from the check-in log, by session. Distinct by learner so a second scan does not count twice.	*/
const logRows_ary = $('Read Check-in Log').all().map(function (item_obj) { return item_obj.json; });
const walkIns_obj = {};
for (const row_obj of logRows_ary)
{
	const outcome_str = String(row_obj.outcome || '');
	if (outcome_str !== 'registered-now' && outcome_str !== 'new-created-registered')
	{
		continue;
	}
	const learner_str = String(row_obj.learnerId || '');
	const session_str = String(row_obj.sessionId || '');
	if (learner_str === '' || session_str === '')
	{
		continue;
	}
	if (!walkIns_obj[session_str])
	{
		walkIns_obj[session_str] = {};
	}
	walkIns_obj[session_str][learner_str] = (String(row_obj.firstName || '') + ' ' + String(row_obj.lastName || '')).trim() || String(row_obj.email || '');
}

const cards_ary = [];
for (const event_obj of events_ary)
{
	let learners_ary = [];
	try
	{
		learners_ary = event_obj.learners.edges.map(function (edge_obj) { return edge_obj.node; });
	} catch (error) {
		learners_ary = [];
	}
	/*	Add the later pages, dropping any learner already seen so an overlapping page cannot count twice.	*/
	const eventId_str = String(event_obj.id);
	const seenLearners_obj = {};
	learners_ary = learners_ary.concat(moreLearners_obj[eventId_str] || []).filter(function (learner_obj)
	{
		if (!learner_obj || seenLearners_obj[String(learner_obj.id)])
		{
			return false;
		}
		seenLearners_obj[String(learner_obj.id)] = true;
		return true;
	});
	let hadMore_bln = false;
	try
	{
		hadMore_bln = !!event_obj.learners.pageInfo.hasNextPage;
	} catch (error) {
		hadMore_bln = false;
	}
	const learnersIncomplete_bln = hadMore_bln && (pagingFailed_bln || !pagingDone_obj[eventId_str]);
	let sessions_ary = [];
	try
	{
		sessions_ary = event_obj.sessions.edges.map(function (edge_obj) { return edge_obj.node; });
	} catch (error) {
		sessions_ary = [];
	}

	for (const session_obj of sessions_ary)
	{
		/*	A session spanning several days appears on each day it covers, starting at its own start time.	*/
		const firstStart_int = Date.parse(String(session_obj.timeZonedStart || ''));
		if (isNaN(firstStart_int))
		{
			continue;
		}
		const endParsed_int = Date.parse(String(session_obj.timeZonedEnd || ''));
		const end_int = isNaN(endParsed_int) ? firstStart_int : endParsed_int;
		let start_int = NaN;
		for (let day_int = 0; day_int < 60; day_int++)
		{
			const occurrence_int = firstStart_int + (day_int * 86400000);
			if (day_int > 0 && occurrence_int > end_int)
			{
				break;
			}
			if (localDate(occurrence_int) === today_str)
			{
				start_int = occurrence_int;
			}
		}
		if (isNaN(start_int))
		{
			continue;
		}
		const sessionId_str = String(session_obj.id);
		const expected_ary = [];
		const checked_ary = [];
		for (const learner_obj of learners_ary)
		{
			const contact_obj = learner_obj.contact || {};
			const name_obj = contact_obj.personalName || {};
			const person_obj = {
				name: (String(name_obj.firstName || '') + ' ' + String(name_obj.lastName || '')).trim() || '(no name)',
				company: contact_obj.account ? String(contact_obj.account.name || '') : ''
			};
			let present_bln = false;
			try
			{
				for (const detail_edge of learner_obj.attendance.sessionDetail.edges)
				{
					if (String(detail_edge.node.session.id) === sessionId_str && String(detail_edge.node.attendanceMark) === 'Present')
					{
						present_bln = true;
					}
				}
			} catch (error) {}
			/*	A door registration counts as a walk-in only for the session it happened in. On a later day of the	*/
			/*	same course that person is already booked, so they are expected like anybody else.	*/
			if (!(walkIns_obj[sessionId_str] && walkIns_obj[sessionId_str][String(learner_obj.id)]))
			{
				expected_ary.push(Object.assign({ present: present_bln }, person_obj));
			}
			if (present_bln)
			{
				checked_ary.push(person_obj);
			}
		}
		const walkInNames_ary = Object.keys(walkIns_obj[sessionId_str] || {}).map(function (key_str) { return { name: walkIns_obj[sessionId_str][key_str], company: '' }; });
		const open_int = start_int - (openMinutes_int * 60000);
		const close_int = start_int + Math.round(closeHours_num * 3600000);
		let state_str = 'open';
		if (now_int < open_int)
		{
			state_str = 'upcoming';
		} else if (now_int > close_int) {
			state_str = 'closed';
		}
		if (expected_ary.length === 0 && walkInNames_ary.length === 0)
		{
			continue;
		}
		if (learnersIncomplete_bln)
		{
			incompleteEvents_obj[eventId_str] = String(event_obj.title || eventId_str);
		}
		cards_ary.push({
			sessionId: sessionId_str,
			title: String(event_obj.title || ''),
			type: String(event_obj.type || ''),
			start: start_int,
			open: open_int,
			state: state_str,
			expected: expected_ary,
			checked: checked_ary,
			waiting: expected_ary.filter(function (person_obj) { return !person_obj.present; }),
			walkIns: walkInNames_ary
		});
	}
}

cards_ary.sort(function (a_obj, b_obj) { return a_obj.start - b_obj.start; });

const css_str = `
