const listName_str = String(query_obj.list || '');
const listSession_str = String(query_obj.session || '');
let body_str = '';
let title_str = String(config_obj.PAGE_TITLE || 'Check-in dashboard');

if (apiError_str !== '')
{
	body_str += '<div class="db-card db-empty"><p>' + escape(apiError_str) + ' The numbers below may be incomplete.</p></div>';
}

if (listSession_str !== '' && listName_str !== '')
{
	let card_var = null;
	for (const card_obj of cards_ary)
	{
		if (card_obj.sessionId === listSession_str)
		{
			card_var = card_obj;
		}
	}
	const labels_obj = { checked: 'Checked in', waiting: 'Not checked in yet', walkIns: 'Walk-ins', expected: 'Expected' };
	if (card_var === null || !labels_obj[listName_str])
	{
		body_str += '<div class="db-card db-list"><p>That session is not running today.</p></div>';
	} else {
		const people_ary = card_var[listName_str] || [];
		body_str += '<div class="db-card db-list"><h2>' + escape(labels_obj[listName_str]) + ': ' + people_ary.length + '</h2><p class="db-meta">' + escape(card_var.title) + ', ' + escape(localTime(card_var.start)) + '</p><table><tr><th>Name</th><th>Company</th></tr>';
		for (const person_obj of people_ary)
		{
			body_str += '<tr><td>' + escape(person_obj.name) + '</td><td>' + escape(person_obj.company) + '</td></tr>';
		}
		body_str += '</table></div>';
	}
} else if (cards_ary.length === 0) {
	body_str += '<div class="db-card db-empty"><p>No sessions with delegates are running today.</p></div>';
} else {
	for (const card_obj of cards_ary)
	{
		const ready_bln = (card_obj.expected.length > 0 && card_obj.waiting.length === 0);
		let state_str = 'Check-in open';
		if (card_obj.state === 'upcoming')
		{
			state_str = 'Check-in opens ' + localTime(card_obj.open);
		} else if (card_obj.state === 'closed') {
			state_str = 'Check-in closed';
		}
		const base_str = escape(self_str) + '?session=' + encodeURIComponent(card_obj.sessionId) + '&list=';
		body_str += '<section class="db-card' + (ready_bln ? ' db-ready' : '') + '"><h2>' + escape(card_obj.title) + '</h2>'
			+ '<p class="db-meta">Starts ' + escape(localTime(card_obj.start)) + ' &middot; ' + escape(state_str) + (card_obj.type !== '' ? ' &middot; ' + escape(card_obj.type) : '') + '</p>'
			+ '<div class="db-counts">'
			+ '<a href="' + base_str + 'checked"><span class="db-num">' + card_obj.checked.length + '</span><span class="db-label">Checked in</span></a>'
			+ '<a href="' + base_str + 'expected"><span class="db-num">' + card_obj.expected.length + '</span><span class="db-label">Expected</span></a>'
			+ '<a href="' + base_str + 'walkIns"><span class="db-num">' + card_obj.walkIns.length + '</span><span class="db-label">Walk-ins</span></a>'
			+ '</div>'
			+ (ready_bln ? '<p class="db-ready-note">Everyone expected has checked in.</p>' : (card_obj.expected.length === 0 ? '<p class="db-meta db-waiting">No pre-booked delegates, walk-ins only</p>' : '<p class="db-meta db-waiting"><a href="' + base_str + 'waiting">' + card_obj.waiting.length + ' expected still to arrive</a></p>'))
			+ '</section>';
	}
}

if (truncated_bln)
{
	body_str += '<div class="db-card db-empty"><p>More than 100 events overlap today, so some may be missing.</p></div>';
}

const incompleteTitles_ary = Object.keys(incompleteEvents_obj).map(function (key_str) { return incompleteEvents_obj[key_str]; });
if (incompleteTitles_ary.length > 0)
{
	body_str += '<div class="db-card db-empty"><p>Not every delegate could be read for: ' + escape(incompleteTitles_ary.join('; ')) + '. The numbers for these may be too low.</p></div>';
}

/*	Refresh reloads the page the user is on, list views included. An empty href is the current URL with	*/
/*	its query string, so no script is needed. The 60-second background refresh stays on the main view.	*/
const back_str = (listSession_str !== '') ? '<a class="db-back" href="' + escape(self_str) + '">Back to all sessions</a>' : '';
const status_str = '<div class="db-status"><span>Updated ' + escape(localStamp(now_int)) + '</span><a class="db-refresh" href="">Refresh</a>' + back_str + '</div>';
const refreshMeta_str = (listSession_str !== '') ? '' : '<meta http-equiv="refresh" content="' + refresh_int + '">';

const html_str = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">'
	+ '<meta name="robots" content="noindex, nofollow">' + refreshMeta_str + '<title>' + escape(title_str) + '</title><style>' + css_str + '</style></head><body>'
	+ '<header class="db-banner"><h1>' + escape(title_str) + '</h1>' + status_str + '</header><main class="db-wrap">' + body_str + '</main></body></html>';

return [{ json: { html: html_str, sessions: cards_ary.length } }];

/*	=== Events with more delegates than one page holds ===	*/
/*	Fetch Todays Events reads the first page of learners for every event. For each event whose list	*/
/*	carries on, this emits one item per further page, up to LEARNER_MAX_PAGES pages in all, and Fetch More	*/
/*	Learners reads each one. n8n's own pagination cannot move a cursor inside a GraphQL body, so the pages	*/
/*	are worked out here instead: an Administrate cursor is 'Cursor:<row index>' in base64, so page k starts	*/
/*	after row (last row of page 1) + (k - 2) x page size. Pages past the end come back empty, which is cheap.	*/
/*	When no event carries on, a single skip item goes down the other branch so the dashboard still builds.	*/
const config_obj = $('Config').first().json;
const maxPages_int = parseInt(String(config_obj.LEARNER_MAX_PAGES || '5'), 10) || 5;
const pageSize_int = Math.min(100, Math.max(1, parseInt(String(config_obj.LEARNER_PAGE_SIZE || '100'), 10) || 100));

function toCursor(row_int)
{
	return Buffer.from('Cursor:' + row_int, 'utf8').toString('base64');
}

function fromCursor(cursor_str)
{
	try
	{
		const match_ary = Buffer.from(String(cursor_str), 'base64').toString('utf8').match(/^Cursor:(-?\d+)$/);
		return match_ary ? parseInt(match_ary[1], 10) : NaN;
	} catch (error) {
		return NaN;
	}
}

let events_ary = [];
try
{
	events_ary = $('Fetch Todays Events').first().json.data.events.edges.map(function (edge_obj) { return edge_obj.node; });
} catch (error) {
	events_ary = [];
}

const pending_ary = [];
for (const event_obj of events_ary)
{
	let pageInfo_obj = {};
	try
	{
		pageInfo_obj = event_obj.learners.pageInfo || {};
	} catch (error) {
		pageInfo_obj = {};
	}
	if (!pageInfo_obj.hasNextPage)
	{
		continue;
	}
	let lastRow_int = fromCursor(pageInfo_obj.endCursor);
	if (isNaN(lastRow_int))
	{
		lastRow_int = pageSize_int - 1;
	}
	for (let page_int = 2; page_int <= maxPages_int; page_int++)
	{
		pending_ary.push({ json: {
			skip: false,
			eventId: String(event_obj.id),
			page: page_int,
			after: toCursor(lastRow_int + ((page_int - 2) * pageSize_int))
		} });
	}
}

if (pending_ary.length === 0)
{
	return [{ json: { skip: true } }];
}
return pending_ary;
